contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address target, uint value) public payable {
        require(target != address(c), "target must not be c");
        require(target != address(this), "target must not be this");

        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.sendMoney(target, value, ""); if (__ESBMC_reverted()) return;
        reverted = false;
        if (reverted) {
            // unreachable in this simple flow; kept for structure
        }

        uint afterBalance = address(c).balance;
        uint afterDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;

        // The call above is not wrapped in try/catch because the rule logic
        // for a reverted call is only reached if sendMoney would revert.
        // Since sendMoney is onlyOwner and the outer call is made by the owner,
        // a revert can still happen if the target rejects the transfer or has no code.
        assert(
            (!reverted && beforeBalance >= value && afterBalance == beforeBalance - value && afterDeposits == beforeDeposits) ||
            (reverted && afterBalance == beforeBalance && afterDeposits == beforeDeposits)
        );
    }

    receive() external payable {}
}

